import {getLazyTree} from "@/api/base/region";

export default {
  props: ['isShow', 'type', 'detailId'],
  data() {
    return {
      formDetial: {},

      saveLoading: false,
      loading: false,


      rules: {
        type: [{required: true, message: '类型不能为空', trigger: 'change'}],
        userId: [{required: true, message: '人员不能为空', trigger: 'change'}],
      },

      typeList: [
        {
          label: '地市运维团队',
          value: '地市运维团队'
        },
        {
          label: '省运维团队',
          value: '省运维团队'
        },
      ],
      userList: []

    };
  },
  computed: {
    ...mapGetters(["userDetail"]),
  },
  watch: {
    // 'filterSjbmText'(newVal, oldVal) {
    //   this.$refs.sjbmTree.filter(newVal);
    // }
  },
  mounted() {
    //加载上级部门列表
    // knowledgeTree({}).then(res => {
    //   this.options = res.data
    // })
    // console.log('formDetial', this.formDetial)



  },
  methods: {
    typeChange(val){
      controloperationteamUser({ type: val }).then(res=>{
        this.userList = res.data
      })
    },
    submit() {
      this.$refs.submitForm.validate((valid) => {
        if (valid) {
          this.saveLoading = true
          if (this.type === 'add') {
            controloperationteamSave(this.formDetial).then(() => {
              this.$message({
                type: "success",
                message: "新增成功!"
              });
              this.$emit('refreshData');
              this.$emit('close');
            }).catch(err => {

            }).finally(() => {
              this.saveLoading = false
            });
          } else {
            update(this.formDetial).then(() => {
              this.$message({
                type: "success",
                message: "更新成功!"
              });
              this.$emit('refreshData');
              this.$emit('close');
            }).catch(err => {

            }).finally(() => {
              this.saveLoading = false
            });
          }
        }
      })
    },

    getTitle(type) {
      if (type == 'add' || type == 'addchildren') {
        return '新 增';
      } else if (type == 'edit') {
        return '更 新';
      } else if (type == 'see') {
        return '详 情';
      }
      return null;
    },
  }
